/* Operation and audit presentation; all actions use existing guarded handlers. */
(() => { 'use strict';window.GpoOperationView=Object.freeze({create({state,esc,say,tr,successful,statusText,stateClass}){
function operationsView(){
  const all=state.history,q=state.opsQuery.trim().toLowerCase();
  const matchesQuery=h=>!q||`${h.plan?.selection?.setting||''} ${h.plan?.preview?.gpo?.name||''} ${h.approval?.changeReference||''} ${h.plan?.executionUser||''} ${h.result?.state||''}`.toLowerCase().includes(q);
  const matchesFilter=h=>{const value=String(h.result?.state||'').toUpperCase();return state.opsFilter==='ALL'||(state.opsFilter==='SUCCESS'&&GpoUiDomain.classify(h).compliant)||(state.opsFilter==='FAILED'&&/FAIL|REVIEW|PARTIAL/.test(value))||(state.opsFilter==='DRIFT'&&/DRIFT|MISMATCH/.test(value))||value===state.opsFilter;};
  const drift=all.filter(h=>/DRIFT|MISMATCH/.test(String(h.result?.state||'').toUpperCase())),filtered=window.GpoProduct.sortedRuns(all.filter(h=>matchesFilter(h)&&matchesQuery(h)),state.opsSort);
  const metrics=[['ALL',say('Hamısı','All'),all.length],['SUCCESS',say('Təsdiqlənib','Verified'),all.filter(successful).length],['DRIFT','Drift',drift.length],['FAILED',say('Yoxlama tələb edir','Needs review'),all.filter(h=>/FAIL|REVIEW|PARTIAL/.test(String(h.result?.state||'').toUpperCase())).length],['ROLLED_BACK',say('Geri qaytarılıb','Rolled back'),all.filter(h=>String(h.result?.state||'').toUpperCase()==='ROLLED_BACK').length]];
  return `<header class="page-header"><div><span class="page-kicker">${say('DƏYİŞİKLİK JURNALI','CHANGE JOURNAL')}</span><h1>${tr('operations')}</h1><p>${say('Hər dəyişiklik üçün nəticə, yoxlama və bərpa məlumatlarını bir yerdə izləyin.','Track outcome, verification, and recovery details for every change.')}</p></div><a class="page-primary" href="#/benchmark">${say('Yeni plan yarat','Create new plan')} <span>→</span></a></header>
  <section class="ops-summary" aria-label="${say('Əməliyyat xülasəsi','Operation summary')}">${metrics.map(([key,label,count])=>`<button data-ops-filter="${key}" class="summary-card ${state.opsFilter===key?'active':''}"><span>${label}</span><strong>${count}</strong></button>`).join('')}</section>
  ${drift.length?`<section class="attention-panel"><div><span>${say('DİQQƏT','ATTENTION')}</span><h2>${drift.length} ${say('əməliyyatda uyğunsuzluq var','operation(s) have drift')}</h2><p>${say('Canlı vəziyyət gözlənilən nəticədən fərqlənir.','Live state differs from the expected result.')}</p></div><button data-ops-filter="DRIFT">${say('Drift-i göstər','Show drift')}</button></section>`:''}
  <section class="ops-search-panel"><div class="searchbox"><span>⌕</span><input id="ops-search" value="${esc(state.opsQuery)}" placeholder="${say('Control, GPO, dəyişiklik ID-si və ya operator axtarın','Search control, GPO, change ID, or operator')}"></div><div class="product-sort"><span>${filtered.length} ${say('nəticə','result(s)')}</span><select id="ops-sort" aria-label="${say('Əməliyyat sırası','Operation order')}">${[['newest',say('Ən yeni','Newest first')],['oldest',say('Ən köhnə','Oldest first')],['attention',say('Diqqət tələb edənlər','Needs attention first')]].map(([v,l])=>`<option value="${v}" ${state.opsSort===v?'selected':''}>${l}</option>`).join('')}</select></div></section>
  ${window.GpoComponents.activity(state,filtered)}${filtered.length?`<div class="ds-ops-switch" role="group" aria-label="${say('Əməliyyat görünüşü','Operations view')}"><button data-ops-layout="table" aria-pressed="${state.opsLayout==='table'}">${say('Cədvəl','Table')}</button><button data-ops-layout="cards" aria-pressed="${state.opsLayout==='cards'}">${say('Kartlar','Cards')}</button></div>${state.opsLayout==='table'?window.GpoComponents.operations(state,filtered):`<div class="ops-list">${filtered.map(operationCard).join('')}</div>`}`:`<section class="empty-state"><div class="empty-state-icon">≋</div><h2>${q?say('Axtarışa uyğun nəticə yoxdur','No matching result'):say('Hələ əməliyyat yoxdur','No operations yet')}</h2><p>${q?say('Axtarış sözünü və ya filtri dəyişin.','Adjust the search term or filter.'):say('İlk read-only planı Benchmark bölməsindən yaradın. Bütün dəyişikliklər burada görünəcək.','Create the first read-only plan from Benchmark. Every change will appear here.')}</p>${q?`<button data-ops-filter="ALL">${say('Bütününü göstər','Show all')}</button>`:`<a href="#/benchmark">${say('Benchmark-i aç','Open benchmark')} →</a>`}</section>`}`;
}
function auditView(){
  const allowed=['Administrator','Auditor'].includes(state.session?.role);
  if(!allowed)return `<section class="content-card"><h1>${say('Audit girişi məhduddur','Audit access restricted')}</h1><p>${say('Bu səhifə Auditor və Administrator rolları üçündür.','This page is available to Auditor and Administrator roles.')}</p></section>`;
  if(!state.audit)return `<section class="content-card audit-loading"><h1>${say('Audit jurnalı','Audit journal')}</h1><p>${say('Hash-chain audit hadisələri yüklənir…','Loading hash-chain audit events…')}</p><button data-load-audit>${say('Audit-i yüklə','Load audit')}</button></section>`;
  const q=state.auditQuery.trim().toLowerCase(),events=(state.audit.events||[]).filter(e=>!q||`${e.event} ${e.operator} ${e.jobId||''} ${e.controlId||''} ${e.gpoId||''} ${e.createdAt}`.toLowerCase().includes(q));
  return `<div class="hero compact"><div><span class="eyebrow">${say('DƏYİŞMƏZ HADİSƏ JURNALI','APPEND-ONLY EVENT JOURNAL')}</span><h1>${say('Audit','Audit')}</h1><p>${say('Hadisə, operator, vaxt, GPO, correlation ID və chain bütövlüyünü izləyin.','Inspect event, actor, time, GPO, correlation context, and chain integrity.')}</p></div><div class="integrity-card ${state.audit.integrityValid?'ok':'bad'}"><span>${say('CHAIN BÜTÖVLÜYÜ','CHAIN INTEGRITY')}</span><strong>${state.audit.integrityValid?say('Etibarlıdır','Valid'):say('POZULUB','BROKEN')}</strong></div></div>${window.GpoComponents.auditChain(state)}<div class="audit-toolbar"><div class="searchbox"><span>⌕</span><input id="audit-search" value="${esc(state.auditQuery)}" placeholder="${say('Hadisə, operator, GPO və ya correlation axtar…','Search event, actor, GPO, or correlation…')}"></div><button data-export-audit>${say('JSON export','Export JSON')}</button><button data-load-audit>${say('Yenilə','Refresh')}</button></div><div class="audit-event-table" role="table"><div class="audit-event-head" role="row"><span>${say('Vaxt','Time')}</span><span>${say('Hadisə','Event')}</span><span>${say('Operator','Actor')}</span><span>GPO / Control</span><span>Hash</span></div>${events.map(e=>`<div class="audit-event-row" role="row"><span><time datetime="${esc(e.createdAt)}">${new Date(e.createdAt).toLocaleString(state.lang==='az'?'az-AZ':'en-GB')}</time><small>#${e.id}</small></span><span><b>${esc(e.event)}</b><small>${esc(e.jobId||'—')}</small></span><span>${esc(e.operator)}</span><span>${esc(e.gpoId||'—')}<small>${esc(e.controlId||'—')}</small></span><span class="hash-cell" title="${esc(e.hash)}">${esc(String(e.hash||'').slice(0,16))}…</span></div>`).join('')||`<div class="panel-empty">${say('Uyğun audit hadisəsi yoxdur.','No matching audit event.')}</div>`}</div>`;
}
function operationCard(h){const rr=h.result?.refreshResults||[],drift=/DRIFT|MISMATCH|REVIEW|FAIL/.test(String(h.result?.state||'')),m=h.plan?.selection?.setting||'Control';const stages=[['Preview',true],['Approved',!!h.approval],['Backup',!!h.result?.backupId],['Applied',!!h.result?.gpoPublished],['Verified',!!h.result?.linkVerified],['gpupdate',rr.length>0],['Effective',stateClass(h.result?.effectiveStatus)==='ok']];return `<article class="op-card ${drift?'needs-attention':''}"><div class="op-main">${window.GpoComponents.status(state,h.result?.state).html}<div><h2>${esc(m)} · ${esc(h.plan?.preview?.gpo?.name||'GPO operation')}</h2><p>${esc(h.result?.message||'')}</p><div class="op-meta"><span>${esc(h.plan?.preview?.scope?.dn||'—')}</span><span>${esc(h.plan?.executionUser||'—')}</span><span>${new Date(h.updatedAt||0).toLocaleString()}</span>${h.approval?.changeReference?`<span>Change ${esc(h.approval.changeReference)}</span>`:''}${h.correlationId?`<span title="Correlation ID">CID ${esc(h.correlationId.slice(0,12))}</span>`:''}</div></div></div><div class="op-timeline">${stages.map(([label,done])=>`<div class="${done?'done':''}"><b>${done?'✓':'·'}</b><span>${label}</span></div>`).join('')}</div><div class="op-live-diff"><div><small>BEFORE</small><strong>${esc(h.plan?.preview?.previousValue??'Not configured')}</strong></div><div><small>EXPECTED</small><strong>${esc(h.plan?.preview?.desiredValue??'—')}</strong></div><div><small>CURRENT</small><strong>${esc(h.result?.currentValue??'—')}</strong></div></div><div class="op-actions"><button class="product-detail-button" data-inspect="${esc(h.id)}">${say('Detalları aç','View details')} ↗</button><button data-verify="${esc(h.id)}" title="Read current live state">Re-verify</button>${h.plan?.selection?.refresh&&(h.result?.gpoPublished&&h.result?.linkVerified||h.result?.state==='ROLLED_BACK')?`<button data-gpupdate="${esc(h.id)}" title="Explicitly schedule gpupdate /force">gpupdate /force</button>`:''}${drift?`<button class="primary-action" data-replan="${esc(h.id)}">Remediate again</button>`:''}<button data-op-evidence="${esc(h.id)}">Evidence</button>${h.result?.state==='ROLLED_BACK'||!h.result?.backupId?'':`<form data-rollback="${esc(h.id)}"><input name="confirmation" placeholder="ROLLBACK" required aria-label="Type ROLLBACK"><button class="danger-action">Rollback</button></form>`}</div></article>`;}

return {operationsView,auditView};}});})();
